import{_ as e,o,c as a,a2 as r}from"./chunks/framework.CFOYCmPM.js";const p=JSON.parse('{"title":"Chapter 1: Foundations & Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":null}'),i={name:"guide/getting-started.md"};function s(n,t,l,d,c,g){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="chapter-1-foundations-getting-started" tabindex="-1">Chapter 1: Foundations &amp; Getting Started <a class="header-anchor" href="#chapter-1-foundations-getting-started" aria-label="Permalink to &quot;Chapter 1: Foundations &amp; Getting Started&quot;">​</a></h1><p>Welcome to <strong>DayZ Studio</strong>! If you have ever wanted to build your own survival outposts, custom quests, talking NPC traders, or post-apocalyptic storylines in DayZ—without learning complex programming or messing with command-line tools—this textbook is for you.</p><hr><h2 id="💡-the-problem-with-traditional-dayz-modding" tabindex="-1">💡 The Problem with Traditional DayZ Modding <a class="header-anchor" href="#💡-the-problem-with-traditional-dayz-modding" aria-label="Permalink to &quot;💡 The Problem with Traditional DayZ Modding&quot;">​</a></h2><p>Historically, building a custom DayZ server experience required juggling multiple fragile tools:</p><ul><li>Writing C++ style scripts in Bohemia&#39;s <strong>Enforce Script</strong> language.</li><li>Hand-crafting massive JSON configuration files with zero error checking.</li><li>Using command-line binarizers (<code>MakePbo</code>, <code>DSUtils</code>, <code>AddonBuilder</code>).</li><li>Forcing every player joining your server to install heavy framework mods (like <strong>Community Framework (CF)</strong> or <strong>DayZ Expansion</strong>).</li></ul><h3 id="the-dayz-studio-difference" tabindex="-1">The DayZ Studio Difference <a class="header-anchor" href="#the-dayz-studio-difference" aria-label="Permalink to &quot;The DayZ Studio Difference&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Traditional Modding</th><th style="text-align:left;">With DayZ Studio ◈</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Requires heavy frameworks (CF, Dabs, Expansion)</strong></td><td style="text-align:left;"><strong>100% Vanilla Server Compatible.</strong> Zero required frameworks (yet 100% CF &amp; Expansion compatible)</td></tr><tr><td style="text-align:left;"><strong>Manual Enforce script coding</strong></td><td style="text-align:left;"><strong>Visual Node Graphs</strong> for quests and NPC logic</td></tr><tr><td style="text-align:left;"><strong>Manual coordinates in <code>init.c</code> to delete trees/walls</strong></td><td style="text-align:left;"><strong>1-Click Object Eraser</strong> in 3D with automatic AI navmesh updates</td></tr><tr><td style="text-align:left;"><strong>5–10 min repack &amp; restart loop to test changes</strong></td><td style="text-align:left;"><strong>Docked In-Engine Viewport</strong> with real Central Economy (&lt;10s)</td></tr><tr><td style="text-align:left;"><strong>Manual keypair generation &amp; signing</strong></td><td style="text-align:left;"><strong>1-Click Cryptographic Signing &amp; Steam Workshop Upload</strong></td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>Freedom of Choice (Vanilla or Heavily Modded):</strong> DayZ Studio eliminates mandatory dependencies so pure vanilla servers can run custom quests, traders, and outposts without forcing players to download third-party frameworks. However, <strong>Community Framework (CF), Dabs Framework, and DayZ Expansion are still completely compatible options</strong>. If your server already runs them, DayZ Studio coexists with them seamlessly: you can import Expansion <code>.map</code> files, load CF-dependent mods in the mod manager, and run on heavily modded servers with zero conflicts.</p></div><hr><h2 id="🧰-key-concepts-vocabulary" tabindex="-1">🧰 Key Concepts &amp; Vocabulary <a class="header-anchor" href="#🧰-key-concepts-vocabulary" aria-label="Permalink to &quot;🧰 Key Concepts &amp; Vocabulary&quot;">​</a></h2><p>Before we install anything, let&#39;s establish a beginner-friendly foundation:</p><ul><li><strong>PBO (<code>.pbo</code>):</strong> Short for <em>Packed Bohemia Object</em>. Think of it as a <code>.zip</code> file specifically formatted for DayZ. All scripts, models, textures, and sounds are packed into <code>.pbo</code> files.</li><li><strong>Cryptographic Keys (<code>.bikey</code> &amp; <code>.biprivatekey</code>):</strong> DayZ requires security keys to protect against cheating. Your <strong>private key</strong> signs your mod. Your <strong>public key</strong> (<code>.bikey</code>) is copied to the server&#39;s <code>keys/</code> directory so the server allows players to join.</li><li><strong>Central Economy (CE):</strong> DayZ&#39;s automated engine system that manages loot spawning, zombie distributions, and animal populations.</li><li><strong>Vanilla Compatible (With Full Mod Framework Support):</strong> Your mod runs out of the box on standard DayZ servers without requiring players to download third-party frameworks. However, if your server already uses Community Framework (CF), Dabs Framework, or DayZ Expansion, DayZ Studio is 100% compatible with them.</li></ul><hr><h2 id="🚀-prerequisites-free-on-steam" tabindex="-1">🚀 Prerequisites (Free on Steam) <a class="header-anchor" href="#🚀-prerequisites-free-on-steam" aria-label="Permalink to &quot;🚀 Prerequisites (Free on Steam)&quot;">​</a></h2><p>Ensure the following tools are installed on your Windows PC:</p><ol><li><strong>DayZ (Game Client):</strong> Your normal Steam installation. DayZ Studio reads authentic terrain, buildings, and textures directly from your local game files.</li><li><strong>DayZ Tools:</strong> Free on Steam under <strong>Library ▸ Tools ▸ DayZ Tools</strong>.<div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>You <strong>must</strong> launch DayZ Tools at least once after installing it. This allows it to write its internal registry paths to Windows so Studio can use its cryptographic signing tools.</p></div></li><li><strong>DayZ Server (Optional):</strong> Also free under Steam Tools. Recommended if you want to test multiplayer server networking directly inside the IDE.</li></ol><hr><h2 id="📥-installing-dayz-studio" tabindex="-1">📥 Installing DayZ Studio <a class="header-anchor" href="#📥-installing-dayz-studio" aria-label="Permalink to &quot;📥 Installing DayZ Studio&quot;">​</a></h2><ol><li>Download <strong><code>DayZStudio-Setup-&lt;version&gt;.exe</code></strong> from the <a href="https://github.com/ghosthex-dev/dayz-studio/releases/latest" target="_blank" rel="noreferrer">GitHub Releases</a>.</li><li>Run the installer.<div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>Windows SmartScreen:</strong> Because DayZ Studio is an independent alpha tool, Windows may display <em>&quot;Windows protected your PC&quot;</em>. Click <strong>More info</strong>, then <strong>Run anyway</strong>.</p></div></li><li>DayZ Studio installs to <code>%LOCALAPPDATA%\\DayZStudio</code> without requiring administrator privileges.</li><li>Your personal projects, custom currency textures, and security keys live safely in: <code>Documents\\DayZStudio</code></li></ol><hr><h2 id="⚙️-the-first-time-map-extraction-10-min-once-per-map" tabindex="-1">⚙️ The First-Time Map Extraction (~10 min, once per map) <a class="header-anchor" href="#⚙️-the-first-time-map-extraction-10-min-once-per-map" aria-label="Permalink to &quot;⚙️ The First-Time Map Extraction (~10 min, once per map)&quot;">​</a></h2><p>Because DayZ Studio respects Bohemia Interactive&#39;s copyright, <strong>it redistributes zero proprietary game files.</strong> Instead, on first run, it extracts terrain elevation and 3D buildings directly from your own legally owned DayZ game:</p><ol><li>Open DayZ Studio and go to the <strong>Map</strong> tab (<code>Alt + 1</code>).</li><li>In the right-hand panel, click <strong>⬇ Extract … imagery from DayZ</strong>.</li><li>Switch to the <strong>Game setup</strong> tab on the left: <ul><li>Click <strong>⬇ Capture from the game</strong> (DayZ will launch briefly to measure terrain elevations, then close automatically).</li><li>Click <strong>☰ Capture class list</strong> (~5,000 items, weapons, vehicles, and props are cataloged).</li></ul></li><li>Click <strong>🌲 Capture world objects</strong> (~3 minutes). This builds the high-speed 3D streaming scene so you can see all natural trees, rocks, and buildings in real-time.</li></ol><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p><strong>Mod Terrains:</strong> Chernarus+, Livonia, Sakhal, and Nasdara are supported out of the box. Community maps like <strong>Namalsk</strong> and <strong>Deer Isle</strong> are also automatically discovered from your Workshop subscriptions!</p></div>',25)])])}const m=e(i,[["render",s]]);export{p as __pageData,m as default};
